#pragma once
#include <filesystem>
#include <fstream>
#include <sstream>
#include <Windows.h>
namespace campaignFiles {
inline std::filesystem::path root(){wchar_t path[32768];DWORD n=GetEnvironmentVariableW(L"FRONTIERE_DATA_DIR",path,32768);if(n>0&&n<32768)return path;n=GetEnvironmentVariableW(L"LOCALAPPDATA",path,32768);if(!n||n>=32768)throw std::runtime_error("Cartella dati utente non disponibile");return std::filesystem::path(path)/L"ChroniclesOfTheAbyss-2-preview";}
inline std::string& activeSlot(){static std::string id;return id;}
inline bool select(const std::string& id){if(id.size()>64||!std::all_of(id.begin(),id.end(),[](char c){return (c>='0'&&c<='9')||(c>='a'&&c<='z')||c=='-'||c=='_';}))return false;activeSlot()=id;return true;}
inline std::filesystem::path folder(const std::string& id){return id.empty()?root():root()/L"campagne"/id;}
inline std::filesystem::path storage(){return folder(activeSlot());}
inline bool commit(const std::filesystem::path& temporary,const std::filesystem::path& destination){return MoveFileExW(temporary.c_str(),destination.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)!=0;}
inline int progress(){std::ifstream in(storage()/L"campagna.progresso");std::string header;int version=0,n=0;if(!(in>>header>>version>>n)||header!="FRONTIERE_PROGRESS"||version!=1||n<0||n>alpha::missionCount)return 0;in>>std::ws;return in.eof()?n:0;}
inline bool progress(int n){if(n<0||n>alpha::missionCount)return false;std::error_code error;auto dir=storage();std::filesystem::create_directories(dir,error);if(error)return false;auto dest=dir/L"campagna.progresso",temp=dir/L"campagna.progresso.tmp";{std::ofstream out(temp);out<<"FRONTIERE_PROGRESS 1 "<<n<<'\n';out.close();if(!out)return false;}return commit(temp,dest);}
inline std::filesystem::path savePath(){return storage()/L"campagna.sav";}
inline std::filesystem::path autoPath(){return storage()/L"campagna-auto.sav";}
inline std::filesystem::path latest(const std::string& id,bool newest=true){auto manual=folder(id)/L"campagna.sav",automatic=folder(id)/L"campagna-auto.sav";std::error_code error;if(!std::filesystem::exists(manual,error))return automatic;if(!newest||!std::filesystem::exists(automatic,error))return manual;auto mt=std::filesystem::last_write_time(manual,error);if(error)return manual;auto at=std::filesystem::last_write_time(automatic,error);return !error&&at>mt?automatic:manual;}
inline std::filesystem::path recoverable(const std::string&,bool newest=true);
inline std::filesystem::path continuePath(bool newest=true){return recoverable(activeSlot(),newest);}
struct Record{std::string id,stamp;int faction=0,mission=0;bool legacy=false;std::filesystem::file_time_type modified{};};
inline bool inspect(const std::filesystem::path& path,Record& record){std::error_code ec;if(std::filesystem::file_size(path,ec)>4*1024*1024||ec)return false;std::ifstream in(path);std::string header;int version;float x,y,z;alpha::World world;if(!(in>>header>>version>>x>>y>>z)||header!="FRONTIERE_CAMPAIGN"||version!=1||!world.restore(in)||world.mission<0||!std::isfinite(x)||!std::isfinite(y)||!std::isfinite(z)||x<0||x>world.width()||y<0||y>world.height()||z<.65f||z>1.4f)return false;record.faction=world.faction[0];record.mission=world.mission;record.modified=std::filesystem::last_write_time(path,ec);return !ec;}
inline std::filesystem::path recoverable(const std::string& id,bool newest){auto preferred=latest(id,newest);Record probe;if(inspect(preferred,probe))return preferred;for(const auto& path:{folder(id)/L"campagna.sav",folder(id)/L"campagna-auto.sav"})if(path!=preferred&&inspect(path,probe))return path;return preferred;}
inline std::vector<Record> records(){std::vector<Record> out;Record legacy;legacy.legacy=true;legacy.stamp="Campagna precedente";if(inspect(recoverable(""),legacy))out.push_back(legacy);std::error_code ec;auto campaigns=root()/L"campagne";std::filesystem::directory_iterator dirs(campaigns,ec);if(!ec)for(const auto& entry:dirs){if(!entry.is_directory(ec)||ec)continue;Record r;r.id=entry.path().filename().string();if(r.id.size()>64||!std::all_of(r.id.begin(),r.id.end(),[](char c){return (c>='0'&&c<='9')||(c>='a'&&c<='z')||c=='-'||c=='_';}))continue;std::ifstream meta(entry.path()/L"campagna.info");std::string header;int version,faction;if(!(meta>>header>>version>>faction>>std::quoted(r.stamp))||header!="CHRONICLES_SLOT"||version!=1||faction<0||faction>1||r.stamp.size()>80)continue;if(inspect(recoverable(r.id),r))out.push_back(r);}
 std::stable_sort(out.begin(),out.end(),[](const Record& a,const Record& b){return a.modified>b.modified;});return out;}
inline bool create(int faction){if(faction<0||faction>1)return false;FILETIME ft;GetSystemTimeAsFileTime(&ft);ULARGE_INTEGER tick;tick.LowPart=ft.dwLowDateTime;tick.HighPart=ft.dwHighDateTime;std::error_code ec;std::filesystem::create_directories(root()/L"campagne",ec);if(ec)return false;std::string id;for(unsigned i=0;i<100;++i){std::ostringstream name;name<<std::hex<<(tick.QuadPart+i);id=name.str();if(std::filesystem::create_directory(folder(id),ec))break;if(ec)return false;id.clear();}if(id.empty())return false;SYSTEMTIME now;GetLocalTime(&now);std::ostringstream stamp;stamp<<std::setfill('0')<<now.wYear<<'-'<<std::setw(2)<<now.wMonth<<'-'<<std::setw(2)<<now.wDay<<' '<<std::setw(2)<<now.wHour<<':'<<std::setw(2)<<now.wMinute<<':'<<std::setw(2)<<now.wSecond;
 {std::ofstream meta(folder(id)/L"campagna.info");meta<<"CHRONICLES_SLOT 1 "<<faction<<' '<<std::quoted(stamp.str())<<'\n';meta.close();if(!meta)return false;}auto previous=activeSlot();select(id);if(!progress(0)){select(previous);return false;}return true;}
}
